// static
bool StructTraits<::actor_internals::mojom::JournalEntry::DataView, ::actor_internals::mojom::JournalEntryPtr>::Read(
    ::actor_internals::mojom::JournalEntry::DataView input,
    ::actor_internals::mojom::JournalEntryPtr* output) {
  bool success = true;
  ::actor_internals::mojom::JournalEntryPtr result(::actor_internals::mojom::JournalEntry::New());
  
      if (success && !input.ReadUrl(&result->url))
        success = false;
      if (success && !input.ReadEvent(&result->event))
        success = false;
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadDetails(&result->details))
        success = false;
      if (success && !input.ReadTimestamp(&result->timestamp))
        success = false;
      if (success)
        result->task_id = input.task_id();
      if (success && !input.ReadTrack(&result->track))
        success = false;
      if (success && !input.ReadScreenshot(&result->screenshot))
        success = false;
      if (success && !input.ReadIframeScreenshot(&result->iframe_screenshot))
        success = false;
  *output = std::move(result);
  return success;
}

